package com.therobbots.player;
import android.app.*;import android.os.*;import android.content.*;import android.database.Cursor;import android.graphics.Color;import android.graphics.drawable.GradientDrawable;import android.media.MediaPlayer;import android.net.Uri;import android.provider.DocumentsContract;import android.text.*;import android.view.*;import android.widget.*;import java.util.*;
public class MainActivity extends Activity {
final int BG=Color.rgb(7,9,13), GOLD=Color.rgb(240,192,94),RED=Color.rgb(196,32,45), PANEL=Color.rgb(20,23,30); LinearLayout root,list,footer;EditText search;MediaPlayer player;Uri folder;ArrayList<Song> songs=new ArrayList<>(),queue=new ArrayList<>();int current=-1;boolean shuffle=false;
static class Song {Uri uri;String title,album;Song(Uri u,String t,String a){uri=u;title=t;album=a;}}
public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);String saved=getPreferences(0).getString("folder",null);if(saved!=null){folder=Uri.parse(saved);scan();}draw();}
TextView text(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setPadding(12,14,12,14);return t;}
GradientDrawable bg(int color){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(30);d.setStroke(2,Color.rgb(100,38,43));return d;}
void draw(){root=new LinearLayout(this);root.setOrientation(1);root.setPadding(22,18,22,18);root.setBackgroundColor(BG);setContentView(root);TextView title=text("THE ROBBOTS",28,GOLD);title.setTypeface(null,1);root.addView(title);root.addView(text("BY ROD PEN    /    IRON EDITION",11,RED));Button select=new Button(this);select.setText(folder==null?"Seleccionar carpeta The Robbots":"Cambiar carpeta / Actualizar");select.setTextColor(GOLD);select.setBackground(bg(PANEL));root.addView(select);select.setOnClickListener(v->{if(folder==null)choose();else{scan();draw();}});root.addView(text(songs.size()+" canciones en tu biblioteca",14,GOLD));search=new EditText(this);search.setSingleLine(true);search.setTextColor(-1);search.setHintTextColor(GOLD);search.setHint("⌕  Buscar álbum o canción");search.setTextSize(15);search.setPadding(20,14,20,14);search.setBackground(bg(PANEL));root.addView(search);ScrollView scroll=new ScrollView(this);list=new LinearLayout(this);list.setOrientation(1);scroll.addView(list);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));footer=new LinearLayout(this);footer.setOrientation(1);footer.setPadding(14,12,14,12);footer.setBackground(bg(PANEL));root.addView(footer);search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int a,int b,int c){albums(s.toString());}public void afterTextChanged(Editable e){}});albums("");controls();}
void choose(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE);i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);startActivityForResult(i,42);}
protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==42&&c==RESULT_OK&&d!=null){folder=d.getData();getContentResolver().takePersistableUriPermission(folder,Intent.FLAG_GRANT_READ_URI_PERMISSION);getPreferences(0).edit().putString("folder",folder.toString()).apply();scan();draw();}}
void scan(){songs.clear();if(folder==null)return;try{walk(DocumentsContract.getTreeDocumentId(folder),"",0);}catch(Exception e){Toast.makeText(this,"Error leyendo carpeta",1).show();}Collections.sort(songs,(a,b)->(a.album+a.title).compareToIgnoreCase(b.album+b.title));}
void walk(String id,String album,int depth){if(depth>7)return;Uri children=DocumentsContract.buildChildDocumentsUriUsingTree(folder,id);try(Cursor c=getContentResolver().query(children,new String[]{DocumentsContract.Document.COLUMN_DOCUMENT_ID,DocumentsContract.Document.COLUMN_DISPLAY_NAME,DocumentsContract.Document.COLUMN_MIME_TYPE},null,null,null)){if(c==null)return;while(c.moveToNext()){String child=c.getString(0),name=c.getString(1),mime=c.getString(2);if(DocumentsContract.Document.MIME_TYPE_DIR.equals(mime))walk(child,depth==0?name:album,depth+1);else if(name.toLowerCase(Locale.ROOT).matches(".*\\.(mp3|m4a|wav|flac|ogg)"))songs.add(new Song(DocumentsContract.buildDocumentUriUsingTree(folder,child),name.replaceFirst("(?i)\\.(mp3|m4a|wav|flac|ogg)$",""),album.isEmpty()?"The Robbots":album));}}catch(Exception ignored){}}
void albums(String filter){list.removeAllViews();LinkedHashMap<String,ArrayList<Song>> groups=new LinkedHashMap<>();for(Song s:songs)if(s.title.toLowerCase().contains(filter.toLowerCase())||s.album.toLowerCase().contains(filter.toLowerCase()))groups.computeIfAbsent(s.album,k->new ArrayList<>()).add(s);for(String name:groups.keySet()){ArrayList<Song> tracks=groups.get(name);TextView t=text("◈   "+name+"\n       "+tracks.size()+" temas",17,GOLD);t.setBackground(bg(PANEL));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,7,0,7);list.addView(t,p);t.setOnClickListener(v->tracks(tracks));}if(songs.isEmpty())list.addView(text("Seleccioná tu carpeta The Robbots.",17,GOLD));}
void tracks(ArrayList<Song> tracks){list.removeAllViews();TextView back=text("‹  Volver a discos",19,GOLD);list.addView(back);back.setOnClickListener(v->albums(search.getText().toString()));for(int i=0;i<tracks.size();i++){final int index=i;TextView t=text((i+1)+".   "+tracks.get(i).title,15,-1);list.addView(t);t.setOnClickListener(v->{queue=new ArrayList<>(tracks);play(index);});}}
void controls(){footer.removeAllViews();TextView now=text(current>=0&&current<queue.size()?queue.get(current).title:"THE ROBBOTS  •  MI MÚSICA",15,GOLD);now.setGravity(Gravity.CENTER);now.setSingleLine(true);now.setEllipsize(android.text.TextUtils.TruncateAt.END);footer.addView(now);TextView subtitle=text(current>=0&&current<queue.size()?queue.get(current).album:"IRON EDITION",11,Color.rgb(173,168,163));subtitle.setGravity(Gravity.CENTER);footer.addView(subtitle);LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);footer.addView(bar);button(bar,shuffle?"⤨ •":"⤨",()->{shuffle=!shuffle;controls();});button(bar,"❮❮",()->next(-1));reactor(bar);button(bar,"❯❯",()->next(1));button(bar,"⟳",()->{scan();draw();});}
void button(LinearLayout bar,String label,Runnable action){TextView b=text(label,21,GOLD);b.setGravity(Gravity.CENTER);bar.addView(b,new LinearLayout.LayoutParams(0,66,1));b.setOnClickListener(v->action.run());}
void reactor(LinearLayout bar){TextView b=text(player!=null&&player.isPlaying()?"Ⅱ":"▶",30,Color.rgb(225,250,255));b.setGravity(Gravity.CENTER);GradientDrawable ring=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{Color.rgb(22,90,111),Color.rgb(7,30,46),Color.rgb(30,110,137)});ring.setShape(GradientDrawable.OVAL);ring.setStroke(5,GOLD);b.setBackground(ring);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(84,84);p.setMargins(4,0,4,0);bar.addView(b,p);b.setOnClickListener(v->{if(player==null){queue=new ArrayList<>(songs);play(0);}else if(player.isPlaying())player.pause();else player.start();controls();});}
void play(int i){if(queue.isEmpty())return;current=Math.max(0,Math.min(i,queue.size()-1));try{if(player!=null)player.release();player=new MediaPlayer();player.setDataSource(this,queue.get(current).uri);player.setOnPreparedListener(mp->{mp.start();controls();});player.setOnCompletionListener(mp->next(1));player.prepareAsync();controls();}catch(Exception e){Toast.makeText(this,"No se pudo reproducir",1).show();}}
void next(int direction){if(queue.isEmpty())queue=new ArrayList<>(songs);if(queue.isEmpty())return;int i=shuffle?new Random().nextInt(queue.size()):(current+direction+queue.size())%queue.size();play(i);}
protected void onDestroy(){if(player!=null)player.release();super.onDestroy();}
}